  insert into public.brands (name, website, description, country, status) values ('House of Elévara', 'https://houseofelevara.com', 'US luxury house selling fragrance and leather goods through shop.houseofelevara.com; its Ambassador Program pays commission on every sale through a personal link, starting at 10% and rising to 25% with lifetime sales, and its own program page states there is no cap and no ceiling on earnings.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'admin@houseofelevara.com', null, 'https://houseofelevara.com/ambassador.html', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://houseofelevara.com/ambassador.html.', 'https://houseofelevara.com/ambassador.html', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'House of Elévara Ambassador Program (brand direct)', 'https://houseofelevara.com/ambassador.html', 'https://houseofelevara.com/ambassador.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://houseofelevara.com/ambassador.html', 'official_site', 'commission_cap', 'The brand''s own Ambassador Program page states ''Commission begins at 10% and rises to 25% as you sell. No cap. No expiration.'' and, under ''No Cap, No Expiry'', ''There is no ceiling on what you earn and no expiration on your link.'' The page also shows the earning ceiling as ''∞''. This is an explicit no-earnings-cap statement on the brand''s own page, so commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://houseofelevara.com/ambassador.html', 'official_site', 'affiliate', 'Program tiers from the same page: Ambassador 10% from the first sale, Signature 15% unlocked at $2,500 lifetime sales, Maison 25% unlocked at $10,000 lifetime sales; tiers never reset. Free to join, no activation fee, no buy-in or inventory; commission is calculated on completed, non-refunded orders and paid monthly. The inaugural collection is led by N° 01 The Parfum ($240 retail), with leather goods arriving in sequence. The contact email admin@houseofelevara.com and phone +1 (307) 289-4953 are published at the foot of the page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://houseofelevara.com/ambassador.html', 'official_site', 'creator_saturation', 'No absolute creator or ambassador count is published on the page checked; the brand is newly launched, but a launch date alone is not low-saturation evidence, so creator_saturation is recorded as unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 19, 13, 9, 3, '{"niche_fit": "Fragrance-led luxury house; the Parfum is the available hero product, with leather goods still arriving, so the promotable catalog is narrow for beauty creators today.", "ugc_evidence": "A named Ambassador Program built around personal-link selling, with editorial features for active ambassadors and no following-size requirement.", "compensation": "10% starting rate rising permanently to 15% and 25% at lifetime-sales tiers, with an explicitly uncapped, no-ceiling statement on the brand''s own page.", "contact_access": "A published contact email and phone number on the program page itself.", "opportunity_availability": "Free to join with no activation fee, buy-in, minimum purchase or exclusivity.", "credibility": "A very new, small house with a short track record and a collection still rolling out."}'::jsonb);
