  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mariam''s Collection Ambassador Program', 'https://mariam-col.com/en-gb/pages/ambassador', 'https://mariam-col.com/en-gb/pages/ambassador', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mariam-col.com/en-gb/pages/ambassador', 'official_site', 'affiliate', 'The brand''s own ambassador page publishes the program: Content Creator affiliates earn 10% commission on every completed order with a 30-day cookie and no approval needed, rising through tiers to 12% (15+ orders/month) and 15% (30+ orders/month), paid monthly on the 15th via PayPal (min $50) or Wise (min $100).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mariam-col.com/en-gb/pages/ambassador', 'official_site', 'commission_cap', 'The same official page states verbatim: ''Receive 10% commission on every completed order through your unique link — accurately tracked, no cap on earnings.'' That explicit no-cap statement on the brand''s own program page is why commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mariam-col.com/en-gb/pages/ambassador', 'official_site', 'ugc_collab', 'The program is built for creators: the page welcomes Instagram, TikTok, YouTube, blog and newsletter promotion, allows boosting your own posts, and active ambassadors at 15+ sales/month receive gifted pieces plus ready-to-use campaign assets for Ramadan, Eid and launches.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mariam-col.com/en-gb/pages/ambassador', 'official_site', 'contact', 'The official page publishes the affiliate team''s email, Affiliate@mariam-col.com, for program assignment questions, paid-search approvals and coupon-platform registration.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mariam-col.com/en-gb/pages/ambassador', 'official_site', 'affiliate', 'Onboarding mechanics from the same page: everyone starts as a Starter Ambassador at 5% with a 7-day cookie during a 3-5 business day review, and confirmed orders are backdated to the 10% Content Creator rate once assigned; a separate Paid & Deal track pays a flat 5% with a 7-day cookie to approved search/coupon partners.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 14, 12, 9, 3, '{"compensation": "Published 10% base creator rate rising to 15% by volume, with an explicit no-cap statement on the brand''s own page and transparent monthly payout terms.", "contact_access": "A dedicated affiliate email (Affiliate@mariam-col.com) and an on-page application form are both published on the official program page.", "credibility": "A smaller direct-to-consumer brand, but the program page is unusually complete and transparent, with full terms, tiers and payout rules published.", "niche_fit": "Modest fashion (abayas and hijabs) is an underserved, high-loyalty fashion niche with a clearly defined creator community.", "opportunity_availability": "The Content Creator track needs no approval \u2014 creators can start immediately \u2014 with assignment review inside 3-5 business days.", "ugc_evidence": "The ambassador program is designed around social creators, with gifted products at volume, campaign assets and explicit permission to boost creator posts."}'::jsonb);
