  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shiridiamonds.com/affiliates/', 'official_site', 'affiliate', 'Shiri Diamonds'' own affiliate page and terms (last updated 3 October 2026) describe the program: affiliates promote with a unique promo code or referral link and every successful purchase made through the code generates a commission of up to 5% per order, tracked in a real-time dashboard and paid via PayPal once the minimum threshold is reached; joining is free with no setup fees.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shiridiamonds.com/affiliates/', 'official_site', 'commission_cap', 'The brand''s own FAQ answers the earnings question twice with: ''How much can I earn as an affiliate? There is no earning limit. Your income depends on how many people use your promo code and complete a purchase.'' That explicit no-limit statement in the program''s own FAQ is why commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shiridiamonds.com/affiliates/', 'official_site', 'ugc_collab', 'The same page explicitly recruits social creators: it says affiliates earn by sharing codes on social media, blogs, WhatsApp, TikTok and Instagram, that no large audience is needed to start, and that even small accounts and micro-influencers can generate monthly income.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 8, 6, 9, 2, '{"compensation": "The only published figure is up to 5% per order \u2014 modest for jewelry \u2014 though the brand''s own FAQ explicitly states there is no earning limit.", "contact_access": "Registration is on the brand''s own affiliate page, but no partnerships email is published on the fetched page.", "credibility": "A small online jeweler with a thin public footprint compared with established jewelry houses; program terms were updated in October 2026, indicating the program is actively maintained.", "niche_fit": "Diamond jewelry fits luxury-fashion and gifting creators, though it is a narrower niche than apparel.", "opportunity_availability": "Free to join, promo code generated instantly after approval, and the brand explicitly welcomes accounts with no large following.", "ugc_evidence": "The program is pitched directly at social media sharing and micro-influencers on its own page, but there is no separate ambassador or gifting program documented."}'::jsonb);
