  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cellulardata.ubigi.com/pro/travel-industry/connectivity-for-international-travelers/', 'official_site', 'affiliate', 'Ubigi''s travel-industry partner page describes a separate ''Ubigi Associate Program'' for airlines, tour operators, OTAs and other travel businesses paying 15% commission on data-plan sales via Impact under a partnership contract — a B2B route distinct from the 10% creator/affiliate program.', 'verified', now());
