  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 12, 12, 8, 4, '{"compensation": "A published 10% commission on the brand''s own affiliate page (15% exists only on the separate B2B associate contract route).", "contact_access": "The program email affiliates@ubigi.com and an application form are published on the official affiliate page.", "credibility": "Established global eSIM provider (Transatel''s consumer brand) selling data plans in over 200 destinations, with featured named affiliate partners on its own page.", "niche_fit": "Travel eSIMs are a staple recommendation in travel content \u2014 high fit for travel creators across blogs, YouTube and TikTok.", "opportunity_availability": "Open application through Impact from the brand''s own affiliate page, subject to Impact approval.", "ugc_evidence": "A dedicated influencer program (Ubigi Roamer Program) plus explicit recruitment of travel bloggers and content creators on the official page."}'::jsonb);
