  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 8, 9, 6, 8, 4, '{"compensation": "A flat $8 per completed booking is published on the official Awin profile and is negotiable for extra exposure \u2014 predictable per-sale pay, though not a percentage of high-value fares.", "contact_access": "No program email is published on the fetched network profile; contact runs through the Awin marketplace.", "credibility": "Established flights-only OTA selling 600+ airlines globally with customer service 7 days a week.", "niche_fit": "Flight booking is a universal travel-content need, and the BNPL payment angle fits budget-travel creators.", "opportunity_availability": "Open to publishers through the Awin marketplace; the profile says the program is ''a great fit for any publisher''.", "ugc_evidence": "A standard publisher affiliate program; no dedicated creator or ambassador program was documented on fetched pages."}'::jsonb);
