  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Made by Nacho Affiliate Program (Impact Radius)', 'https://madebynacho.com/pages/made-by-nacho-affiliate-program', 'https://madebynacho.com/pages/made-by-nacho-affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://madebynacho.com/pages/made-by-nacho-affiliate-program', 'official_site', 'affiliate', 'Made by Nacho''s own affiliate program page states: ''We''ve partnered with Impact Radius to bring you a market-leading affiliate advertising program'' — affiliates promote campaigns on their blog, website, newsletter or search landing page with provided links and creatives and ''earn commission on every sale directed from those links''. No commission rate is published on the page, so the rate is recorded as null.', 'verified', now());
