  insert into public.brands (name, website, description, country, status) values ('PURRZ', 'https://purrz.com', 'Vet-designed cat lifestyle brand founded by Sydney emergency veterinarian Dr Duncan Houston, selling scratchers, caves, trees, toys, litter and everyday cat essentials built around feline instinct.', 'Australia', 'published') returning id into bid;
