  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://purrz.com/pages/ambassador-hub.', 'https://purrz.com/pages/ambassador-hub', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PURRZ Ambassador Programme', 'https://purrz.com/pages/ambassador-hub', 'https://purrz.com/pages/ambassador-hub', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://purrz.com/pages/ambassador-hub', 'official_site', 'compensation', 'PURRZ''s own Ambassador Programme page states the deal twice: ''10% commission — on every sale through your code or link, with no monthly cap'', and its FAQ repeats: ''10% of every sale made through your personal code or link, with no monthly cap.'' The brand''s own page therefore explicitly states there is no cap on commission earnings, so the cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://purrz.com/pages/ambassador-hub', 'official_site', 'ugc_collab', 'The programme is built for creators: ''Creators with a cat — Instagram, TikTok or YouTube, any size'' are invited to apply via Social Snowball (apply links point to purrz.socialsnowball.io); approval is ''on the cat, the content and the audience, not the follower count'', and ambassadors get a personal code/link, a language kit and product images.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.dealgrams.com/blog-detail/purrz-cat-products-review-and-best-sellers-complete-brand-guide', 'listing', 'general', 'DealGrams'' brand guide describes PURRZ as a veterinarian-founded cat lifestyle brand founded by Dr Duncan Houston, a Sydney-based emergency and critical care veterinarian, selling cat furniture, toys, bedding, safety products and accessories.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 15, 6, 9, 3, '{"compensation": "10% on every sale with no monthly cap, stated twice on the brand''s own page \u2014 a published rate plus a verified uncapped term.", "contact_access": "Application runs through the brand''s Social Snowball form linked from its own page; no public email was shown on the fetched page.", "credibility": "Young, small founder-led brand (a vet-designed label and the sister programme to WOOPF), so brand scale and track record are limited.", "niche_fit": "Cat furniture, toys and litter designed around feline instinct \u2014 highly filmable for cat creators.", "opportunity_availability": "Open application; the brand explicitly approves on content and audience rather than follower count, welcoming small accounts.", "ugc_evidence": "A dedicated creator programme on the brand''s own site, open to creators of any size on Instagram, TikTok or YouTube, with codes, links and a content language kit."}'::jsonb);
